import React, { useState } from 'react';
import { Carousel, Container } from 'react-bootstrap';
import '../About.css'
import { useTranslation } from 'react-i18next';
function Productslider() {
  const { t, i18n } = useTranslation();
  return (
    <div>
      <div className="headertop" >
        <Carousel className="slider ">
          <Carousel.Item>
            <img className="d-block w-100  " src="/products/ourproduct.jpg" alt="ogfc-img" />

            <div className="carousel-caption caption-left">
              <div class="left-line"></div>
              <h1 style={{ fontFamily: t('fontFamilytwo') }} className='linedown ourproducts'>{t("OUR-first")}<br></br>{t("OUR-second")}

              </h1>

            </div>

          </Carousel.Item>
        </Carousel>
      </div>




    </div>
  )
}

export default Productslider